settings.custom_css:
/* Target all headings inside the Elementor Single Post Template */
.elementor-single-post h1,
.elementor-single-post h2,
.elementor-single-post h3,
.elementor-single-post h4,
.elementor-single-post h5,
.elementor-single-post h6 {
    font-family: 'Montserrat', sans-serif !important;
    font-weight: 700; /* Adjust weight as needed: 400, 500, 600, 700, 800 */
}

/* Individual Heading Sizes - Adjust these values to your preference */
.elementor-single-post h1 {
    font-size: 42px !important;
    line-height: 1.2 !important;
    margin-bottom: 20px !important;
}

.elementor-single-post h2 {
    font-size: 32px !important;
    line-height: 1.3 !important;
    margin-bottom: 18px !important;
}

.elementor-single-post h3 {
    font-size: 26px !important;
    line-height: 1.4 !important;
    margin-bottom: 16px !important;
}

.elementor-single-post h4 {
    font-size: 22px !important;
    line-height: 1.4 !important;
    margin-bottom: 14px !important;
}

.elementor-single-post h5 {
    font-size: 18px !important;
    line-height: 1.5 !important;
    margin-bottom: 12px !important;
}

.elementor-single-post h6 {
    font-size: 16px !important;
    line-height: 1.5 !important;
    margin-bottom: 10px !important;
}

selector {
	--cc-text:           #2d3748;
	--cc-heading:        #0a1f3d;
	--cc-accent:         #1a4d5c;
	--cc-muted:          #64748b;
	--cc-rule:           #e2e8f0;
	--cc-rule-strong:    #cbd5e1;
	--cc-link:           #1a4d5c;
	--cc-link-hover:     #0a1f3d;
	--cc-table-header:   #0a1f3d;
	--cc-table-stripe:   #f8fafc;
}

/* ---- Body text + paragraphs ---- */
selector p {
	font-family: 'Inter', 'Montserrat', system-ui, -apple-system, sans-serif !important;
	font-size: 17px !important;
	line-height: 1.75 !important;
	color: var(--cc-text) !important;
	margin: 0 0 1.25em !important;
	letter-spacing: -0.003em !important;
}

/* Strip span cruft so it stops fighting font/color */
selector span[style*="font-weight: 400"],
selector span[style*="font-weight:400"] {
	font-weight: 400 !important;
	color: inherit !important;
	font-family: inherit !important;
}

/* ---- Headings ---- */
selector h2 {
	font-family: 'Inter', 'Montserrat', system-ui, sans-serif !important;
	font-size: 1.75rem !important;
	font-weight: 600 !important;
	color: var(--cc-heading) !important;
	line-height: 1.3 !important;
	letter-spacing: -0.02em !important;
	margin: 2.6em 0 0.7em !important;
	padding-top: 0.7em !important;
	border-top: 1px solid var(--cc-rule-strong) !important;
	text-transform: none !important;
}
selector h3 {
	font-family: 'Inter', 'Montserrat', system-ui, sans-serif !important;
	font-size: 1.25rem !important;
	font-weight: 600 !important;
	color: var(--cc-heading) !important;
	line-height: 1.35 !important;
	margin: 2em 0 0.5em !important;
	letter-spacing: -0.015em !important;
	text-transform: none !important;
}
selector h4 {
	font-family: 'Inter', 'Montserrat', system-ui, sans-serif !important;
	font-size: 1.05rem !important;
	font-weight: 600 !important;
	color: var(--cc-heading) !important;
	margin: 1.5em 0 0.4em !important;
	letter-spacing: -0.01em !important;
	text-transform: none !important;
}
selector h5,
selector h6 {
	font-family: 'Inter', 'Montserrat', system-ui, sans-serif !important;
	font-size: 0.85rem !important;
	font-weight: 600 !important;
	color: var(--cc-muted) !important;
	text-transform: uppercase !important;
	letter-spacing: 0.08em !important;
	margin: 1.4em 0 0.4em !important;
}

/* WP classic-editor wraps heading text in <b>. Stop it doubling up. */
selector h2 b,
selector h3 b,
selector h4 b {
	font-weight: inherit !important;
}

/* ---- Links ---- */
selector p a,
selector li a,
selector td a {
	color: var(--cc-link) !important;
	text-decoration: underline !important;
	text-decoration-thickness: 1px !important;
	text-underline-offset: 3px !important;
	text-decoration-color: var(--cc-rule-strong) !important;
	transition: color 0.15s ease, text-decoration-color 0.15s ease !important;
}
selector p a:hover,
selector li a:hover,
selector td a:hover {
	color: var(--cc-link-hover) !important;
	text-decoration-color: var(--cc-link-hover) !important;
}

/* ---- Lists ---- */
selector ul,
selector ol {
	margin: 0 0 1.5em !important;
	padding-left: 1.5em !important;
}
selector li {
	font-family: 'Inter', 'Montserrat', system-ui, sans-serif !important;
	font-size: 17px !important;
	line-height: 1.7 !important;
	color: var(--cc-text) !important;
	margin-bottom: 0.5em !important;
	letter-spacing: -0.003em !important;
}
selector ul li::marker {
	color: var(--cc-muted);
}
selector ol li::marker {
	color: var(--cc-muted);
	font-weight: 500;
}

/* ---- Tables ---- */
selector table {
	width: 100% !important;
	border-collapse: collapse !important;
	margin: 1.8em 0 !important;
	background: #fff !important;
	border-top: 2px solid var(--cc-heading) !important;
	border-bottom: 2px solid var(--cc-heading) !important;
	font-family: 'Inter', 'Montserrat', system-ui, sans-serif !important;
}

/* Real header row only — no more tbody-first-row fallback */
selector table thead th,
selector table thead td {
	background: transparent !important;
	color: var(--cc-heading) !important;
	font-weight: 600 !important;
	text-align: left !important;
	padding: 0.75em 1em !important;
	font-size: 0.78em !important;
	text-transform: uppercase !important;
	letter-spacing: 0.08em !important;
	border-bottom: 1px solid var(--cc-heading) !important;
}

/* Body cells */
selector table tbody td {
	padding: 0.85em 1em !important;
	color: var(--cc-text) !important;
	font-size: 0.95em !important;
	line-height: 1.6 !important;
	border-bottom: 1px solid var(--cc-rule) !important;
	vertical-align: top !important;
	text-transform: none !important;        /* defensive: kill any inherited uppercase */
	font-weight: 400 !important;            /* defensive: kill any inherited bold */
}

selector table tbody tr:last-child td {
	border-bottom: none !important;
}

/* First column = row label. Subtle weight, not heavy navy. */
selector table tbody td:first-child {
	font-weight: 600 !important;
	color: var(--cc-heading) !important;
	width: 22% !important;
	padding-right: 1.5em !important;
}

/* Neutralize <strong> inside table cells so it doesn't double-bold */
selector table td strong,
selector table td b,
selector table th strong,
selector table th b {
	font-weight: inherit !important;
	color: inherit !important;
	text-transform: none !important;
}

/* Mobile */
@media (max-width: 600px) {
	selector table thead th,
	selector table thead td,
	selector table tbody td {
		padding: 0.65em 0.75em !important;
		font-size: 0.88em !important;
	}
	selector table tbody td:first-child {
		width: auto !important;
	}
}

